        System.out.println(String.join(", ", placas));
    }

    public static void radixSort(String[] placas) {
        // Encontra o número máximo de dígitos no número da placa
        int maxDigits = 0;
        for (String placa : placas) {
            int digits = placa.substring(4).length();
            maxDigits = Math.max(maxDigits, digits);
        }

        // Realiza o radix sort para cada dígito, da direita para a esquerda
        for (int i = 0; i < maxDigits; i++) {
            countingSort(placas, i);
        }
    }

    private static void countingSort(String[] placas, int digitIndex) {
        int[] count = new int[10];
        String[] output = new String[placas.length];

        // Conta a ocorrência de cada dígito na posição especificada
        for (String placa : placas) {
            int digit = Character.getNumericValue(placa.charAt(4 + digitIndex));
            count[digit]++;
        }

        // Calcula a contagem cumulativa
        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        // Constrói o array de saída ordenado
        for (int i = placas.length - 1; i >= 0; i--) {
            String placa = placas[i];
            int digit = Character.getNumericValue(placa.charAt(4 + digitIndex));
            output[count[digit] - 1] = placa;
            count[digit]--;
        }

        // Copia o array de saída de volta para o array de entrada
        System.arraycopy(output, 0, placas, 0, placas.length);
    }
}
