import java.util.Scanner;

class RadixSort {

    public static int[] counting(int[] a, int k, int nthDig) {
        int[] c = new int[k];
        for (int i = 0; i < a.length; i++) {
            int n = extractDigits(a[i], nthDig);
            c[n - 1] += 1;
        }

        for (int i = 1; i < c.length; i++) {
            c[i] += c[i - 1];
        }

        int[] b = new int[a.length];
        for (int i = a.length - 1; i >= 0; i--) {
            int d = extractDigits(a[i], nthDig);
            b[c[d - 1] - 1] = a[i];
            c[d - 1] -= 1;
        }

        return b;
    }

    public static int extractDigits(int n, int nthDig) {
        int d1 = (n % (int) Math.pow(10, nthDig)) / (int) Math.pow(10, nthDig - 1);
        int d2 = (n % (int) Math.pow(10, nthDig + 1)) / (int) Math.pow(10, nthDig);
        return (d2 * 10) + d1;
    }

