    this.visited[node] = true;
    this.reachableFromZero++;

    for(Edge edge: getEdgesFromVertex(node)) {
      if(visited[edge.getEndNode()]) {
        dfs(edge.getEndNode(), node);
      }
      else if(edge.getEndNode() != par) {
        this.hasCycle = true;
        return;
      }
    }
